import{_ as r,o,c as a,ae as e}from"./chunks/framework.RRduUuAx.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-数据库-分布式数据库","description":"","frontmatter":{"title":"架构师-备考 综合知识-数据库-分布式数据库"},"headers":[],"relativePath":"综合知识/数据库/分布式数据库.md","filePath":"综合知识/数据库/分布式数据库.md"}'),n={name:"综合知识/数据库/分布式数据库.md"};function s(d,t,l,i,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 分布式数据库概念与特点</li><li>[x] 分片模式（水平分片/垂直分片）</li><li>[x] 分布透明性（分片/位置/逻辑/复制透明性）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、分布式数据库概念" tabindex="-1">一、分布式数据库概念 <a class="header-anchor" href="#一、分布式数据库概念" aria-label="Permalink to &quot;一、分布式数据库概念&quot;">​</a></h3><blockquote><p><strong>分布式数据库系统（DDBS）</strong>：针对地理上分散，而管理上又需要不同程度集中的需求而提出的一种数据管理信息系统。</p></blockquote><p>满足<strong>分布性、逻辑相关性、场地透明性和场地自治性</strong>的数据库系统被称为<strong>完全分布式数据库系统</strong>。</p><p><strong>核心特点</strong>：数据的集中控制性、数据独立性、数据冗余可控性、场地自治性和存取的有效性。</p><blockquote><p>简单理解：局部数据库位于不同的物理位置，使用一个全局 DBMS 将所有局部数据库联网管理。</p></blockquote><hr><h3 id="二、分片模式" tabindex="-1">二、分片模式 <a class="header-anchor" href="#二、分片模式" aria-label="Permalink to &quot;二、分片模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分片方式</th><th>描述</th></tr></thead><tbody><tr><td><strong>水平分片</strong></td><td>将表中<strong>水平的记录</strong>分别存放在不同的地方（按行拆分）</td></tr><tr><td><strong>垂直分片</strong></td><td>将表中的<strong>垂直的列值</strong>分别存放在不同的地方（按列拆分）</td></tr></tbody></table><hr><h3 id="三、分布透明性" tabindex="-1">三、分布透明性 <a class="header-anchor" href="#三、分布透明性" aria-label="Permalink to &quot;三、分布透明性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>透明性</th><th>含义</th></tr></thead><tbody><tr><td><strong>分片透明性</strong></td><td>用户或应用程序<strong>不需要知道逻辑上访问的表具体是如何分块存储的</strong></td></tr><tr><td><strong>位置透明性</strong></td><td>应用程序<strong>不关心数据存储物理位置的改变</strong></td></tr><tr><td><strong>逻辑透明性</strong>（局部数据模型透明性）</td><td>用户或应用程序<strong>无需知道局部使用的是哪种数据模型</strong></td></tr><tr><td><strong>复制透明性</strong></td><td>用户或应用程序<strong>不关心复制的数据从何而来</strong></td></tr></tbody></table><blockquote><p><strong>层级关系</strong>：分片透明性 &gt; 位置透明性 &gt; 逻辑透明性。分片透明是最高级别的透明性。</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830234235.png" alt="分布透明性"></p>',16)])])}const _=r(n,[["render",s]]);export{b as __pageData,_ as default};
